from lib import *
S = SS('t2')
steps = [
    step("手动走一遍两阶段。阶段一:订单库和库存库各自 BEGIN、执行自己的修改,再各发一条 PREPARE TRANSACTION 'tx-1',两边都返回成功(投 YES)。这时 pg_prepared_xacts 里两边各有一条 tx-1,但别的会话看到的还是订单库 0 条订单、库存 100——两个修改都还不可见。阶段二:两边各发 COMMIT PREPARED 'tx-1',提交后订单库 1 条订单、库存 99,pg_prepared_xacts 清空。PostgreSQL 在这里扮演参与者(资源管理器),协调者是 Python 里自己写的一段代码。", t=tl(S(1)), mark=lidx(S(1), 'prepare 之后别的会话看到'), done=lidx(S(1), '提交后:订单库 1 条'), b=bars([['prepare 之后:订单库订单数', 0, '0(不可见)'], ['prepare 之后:库存', 100, '100(不可见)'], ['commit 之后:订单库订单数', 1, '1'], ['commit 之后:库存', 99, '99']], 100, mark=[0, 1], done=[2, 3]), kv=KV([['阶段一', 'PREPARE TRANSACTION,修改不可见'], ['阶段二', 'COMMIT PREPARED,修改可见'], ['pg_prepared_xacts', 'prepare 后出现,commit 后清空']], ['阶段一'])),
    step("PREPARE 之后协调者的连接关掉,事务并没有消失:pg_prepared_xacts 里还有 tx-2,pg_locks 里有三条没有会话持有(pid 为空)的锁——stock 表和它的主键索引上的 RowExclusiveLock,加上一个 transactionid 的 ExclusiveLock。别的会话 SELECT 读到旧值 qty=100,用时 4.3 ms,没有被挡(MVCC 读不加锁)。别的会话 UPDATE 同一行(lock_timeout=1500ms)等了 1502.0 ms 后报 lock timeout。另开一个会话 UPDATE 同一行阻塞着,1.2 秒后协调者 COMMIT PREPARED,它等了 1206.4 ms 才返回,最终 qty=94(100 - 1 - 5)。prepared 事务是脱离连接存在的,锁一直握到有人提交或回滚它。", t=tl(S(2)), mark=lidx(S(2), '等了 1502.0 ms'), done=lidx(S(2), '它等了 1206.4 ms'), b=bars([['SELECT 用时 ms', 4.3, '4.3'], ['UPDATE 被挡的时间 ms(lock_timeout)', 1502.0, '1502.0'], ['UPDATE 阻塞到协调者提交 ms', 1206.4, '1206.4']], 1600, done=[0], mark=[1, 2]), kv=KV([['读', '读到旧值,不被挡'], ['写同一行', '被挡到有人提交 / 回滚'], ['连接断开', '事务和锁都还在']], ['写同一行'])),
    step("PREPARE 之后整个 PostgreSQL 被 kill -9(postmaster 和全部子进程),重启用了 129.4 ms。重启后 pg_prepared_xacts 里还有 tx-3,别的会话 UPDATE 同一行仍然 lock timeout(行锁在恢复时被重新建起来),COMMIT PREPARED 'tx-3' 成功,qty 变成 99。日志里有 “recovering prepared transaction 739 from shared memory” 和 “1 two-phase state file was written for a long-running prepared transaction”。PREPARE 时参与者就把足够恢复的信息写进了 WAL——这正是“承诺过的事不能反悔”的实现。", t=tl(S(3)), mark=lidx(S(3), '重启后 pg_prepared_xacts', '行锁被恢复了'), done=lidx(S(3), '提交后 qty=99'), kv=KV([['kill -9 之后', 'prepared 事务还在'], ['锁', '恢复时重建'], ['原因', 'PREPARE 时已写进 WAL']], ['原因'])),
    step("代价:同样“建订单 + 扣库存”,放进一个实例里一个事务提交:中位数 0.2 ms,p99 0.5 ms,300 个事务合计 300 次 WAL fsync = 每个事务 1.00 次。跨两个实例做 2PC:中位数 1.1 ms,p99 3.0 ms,合计 1200 次 = 每个事务 4.00 次(两个参与者各 1 次 prepare + 1 次 commit prepared)。中位数 6.9 倍、fsync 4.0 倍;协调者自己写决定日志的 fsync 另算,没算在内。这台笔记本上 fsync 很便宜,磁盘更慢时差距会更大。", t=tl(S(4)), mark=lidx(S(4), '两个实例做 2PC'), done=lidx(S(4), '一个实例里一个事务'), b=bars([['单实例 fsync / 事务', 1.0, '1.00'], ['2PC fsync / 事务', 4.0, '4.00'], ['单实例中位数 ms', 0.2, '0.2'], ['2PC 中位数 ms', 1.1, '1.1']], 4.5, cur=[0, 2], mark=[1, 3]), kv=KV([['fsync 次数', '1 次 → 4 次(2 个参与者)'], ['中位数', '0.2 ms → 1.1 ms(6.9 倍)'], ['不含', '协调者决定日志的 fsync']], ['fsync 次数'])),
    step("阶段一和阶段二之间,行锁一直被持有。协调者在 PREPARE 之后多等 hold 毫秒再提交,两个线程各连续做 20 次 2PC。抢同一行:hold=0 时 307 事务/秒,hold=50 ms 时 18,hold=200 ms 时 5,估算值 1000/(hold + 3.3 ms) 分别是 307、19、5,吻合。两个线程各用各的行:1094、35、10 事务/秒——不同行互不影响,仍然并行,所以同一行的吞吐是被“持锁时间”直接卡死的。2PC 里只要协调者慢一点(网络抖动、GC、等下游),热点行的吞吐就跟着塌。", t=tl(S(5)), mark=lidx(S(5), '200 ms'), done=lidx(S(5), '0 ms ', '50 ms'), b=bars([['hold=0 同一行 事务/秒', 307, '307'], ['hold=50 同一行', 18, '18'], ['hold=200 同一行', 5, '5'], ['hold=200 各用各的行', 10, '10']], 320, mark=[1, 2], done=[3], cur=[0]), kv=KV([['同一行', '吞吐 ≈ 1000 /(hold + 2PC 耗时)'], ['不同行', '互不影响'], ['含义', '持锁时间 = 阶段一到阶段二的间隔']], ['含义'])),
]
A = mkartt('t2', 2, '分布式事务,两阶段提交,2PC,PostgreSQL,PREPARE TRANSACTION,真实验证,动画演示',
    '用两个真实的 PostgreSQL 实例和一个手写协调者实测两阶段提交:prepare 之后修改不可见、断开连接和 kill -9 后事务与行锁仍在;一次提交从 1 次变成 4 次 WAL fsync,中位数慢 6.9 倍;同一行上吞吐 = 1000/(hold + 3.3 ms)。',
    '两阶段提交(2PC)把“多个库一起提交”拆成投票和执行两步。它到底保证了什么、prepare 之后事务处在什么状态、代价是多少?这篇用真实的 PostgreSQL PREPARE TRANSACTION 把每一步都跑出来,并量出它在延迟、fsync 次数和热点行吞吐上的账。',
    [('4 次 vs 1 次', '每个事务的 WAL fsync 次数:跨两个实例做 2PC 对比单实例'), ('6.9 倍', '2PC 对比单实例的提交延迟中位数(1.1 ms 对 0.2 ms)'), ('5 事务/秒', 'prepare 之后多等 200 ms 时,两个线程抢同一行的 2PC 吞吐(不等时是 307)')],
    [('阶段一与阶段二', '<p>阶段一每个参与者执行修改后 PREPARE,把“我能提交”的承诺写进日志;全部 YES 后,协调者在阶段二让大家 COMMIT PREPARED。prepare 之后修改不可见,提交后才可见。</p>'),
     ('prepared 事务脱离连接', '<p>协调者的连接断了,prepared 事务和它的行锁仍在。读(MVCC)不被挡,写同一行被挡到有人提交或回滚。</p>'),
     ('崩溃后还在', '<p>参与者在 PREPARE 时把恢复所需信息写进 WAL。整个实例 kill -9 重启后,prepared 事务和它的锁都被恢复。它承诺过的事,不会因为崩溃而反悔。</p>'),
     ('代价:fsync 与延迟', '<p>两个参与者各一次 prepare、一次 commit prepared,每个事务 4 次 WAL fsync,是单实例的 4 倍;提交延迟中位数 6.9 倍。协调者的决定日志还要再算一次落盘。</p>'),
     ('持锁时间决定热点行吞吐', '<p>行锁从 prepare 一直握到 commit prepared。同一行上的事务只能排队,吞吐约等于 1000/(持锁时间)。协调者慢一点,热点行的吞吐就按比例塌下去。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 PostgreSQL 16.15 实例(max_prepared_transactions=20,wal_sync_method=fsync 以便数 pg_stat_wal.wal_sync),协调者是我自己写的 Python 代码(tools/articles/tpc.py),决定日志在 SQLite 里;PostgreSQL 在 macOS 上的 fsync 不等于写透磁盘缓存,绝对时间偏小,倍数更有参考价值',
     '没有验证:协调者崩溃时参与者怎么办(下一篇做);多于两个参与者时的扩展;跨机器网络下的往返延迟;MySQL 的 XA 实现(第 5 篇);PostgreSQL 以外数据库的 prepare 行为;本机 PostgreSQL 的 wal_sync_method 默认是 open_datasync(查过),按文档 pg_stat_wal.wal_sync 只在 fsync / fdatasync 方式下计数,所以我改成了 fsync;默认方式下每个事务的刷盘次数没有测'],
    '两阶段提交')
